def _attribute_divergence_on_orders(
    self,
    left_order: list[str],
    right_order: list[str],
    head_a: str,
    head_b: str,
    key: str,
) -> dict[str, object]:
    """Divergence attribution on closures captured by the caller.

    Sharing the precomputed replay orders lets
    :meth:`attribute_divergences_at` answer every key from one
    read-only historical view; results are identical to replaying
    the closures per key because replay order is deterministic.
    """
    left_ids = set(left_order)
    right_ids = set(right_order)

    left_value = self._replayed_value(left_order, key)
    right_value = self._replayed_value(right_order, key)

    # Common events form an ancestor-closed set, so the last common
    # event in either side's deterministic replay order is the fork.
    common = tuple(
        event_id
        for event_id in left_order
        if event_id in right_ids
    )
    fork = common[-1] if common else None

    if left_value != right_value:
        left_cause = next(
            (
                event_id
                for event_id in left_order
                if event_id not in right_ids
                and key in self._graph._changes[event_id]
            ),
            None,
        )
        right_cause = next(
            (
                event_id
                for event_id in right_order
                if event_id not in left_ids
                and key in self._graph._changes[event_id]
            ),
            None,
        )
    else:
        left_cause = None
        right_cause = None

    def cause_impact(
        order: list[str], head: str, cause: str | None
    ) -> tuple[tuple[str, ...], tuple[str, ...]]:
        if cause is None:
            return (), ()

        closure = set(order)
        # Reverse the parent edges within the closure so children can
        # be enumerated parent-to-child.
        children: dict[str, list[str]] = {
            event: [] for event in closure
        }
        for current in closure:
            for parent in self._graph._parents[current]:
                if parent in closure:
                    children[parent].append(current)

        # Level-by-level breadth-first search gives the fewest-edge
        # paths; keeping the minimum full id tuple within a level
        # applies the Unicode code point tie-break, as in
        # explain_impact.
        paths: dict[str, tuple[str, ...]] = {cause: (cause,)}
        frontier = [cause]
        while frontier:
            candidates: dict[str, tuple[str, ...]] = {}
            for current in frontier:
                current_path = paths[current]
                for child in children[current]:
                    if child in paths:
                        continue
                    candidate = (*current_path, child)
                    best = candidates.get(child)
                    if best is None or candidate < best:
                        candidates[child] = candidate
            for child, path in candidates.items():
                paths[child] = path
            frontier = list(candidates)

        path = tuple(paths[head])
        affected = tuple(
            event_id
            for event_id in order
            if event_id != cause and event_id in paths
        )
        return path, affected

    left_path, left_affected = cause_impact(
        left_order, head_a, left_cause
    )
    right_path, right_affected = cause_impact(
        right_order, head_b, right_cause
    )

    return {
        "key": key,
        "fork": fork,
        "left": {
            "value": left_value,
            "cause": left_cause,
            "path": left_path,
            "affected": left_affected,
        },
        "right": {
            "value": right_value,
            "cause": right_cause,
            "path": right_path,
            "affected": right_affected,
        },
    }

def head(self, name: str) -> str:
    """Return the id of the branch's current head event."""
    self._require_nonempty_str(name, "name")
    self._require_known_branch(name)
    return self._heads[name]

def replay(self, name: str) -> dict[str, int]:
    """Replay the branch's head via :meth:`EventGraph.replay`."""
    self._require_nonempty_str(name, "name")
    self._require_known_branch(name)
    return self._graph.replay(self._heads[name])

def replay_at(self, name: str, at: int) -> dict[str, int]:
    """Replay the branch's head as of ``at`` via :meth:`EventGraph.replay_at`.

    ``name`` and ``at`` are validated (in that order) before the
    branch is looked up; the query is read-only, so the graph,
    branch heads and records are never modified.
    """
    self._require_nonempty_str(name, "name")
    at_value = EventGraph._require_int(at, "at")
    if at_value < 0:
        raise ValueError("at must be a non-negative int")
    self._require_known_branch(name)
    return self._graph.replay_at(self._heads[name], at_value)

"""In-memory event DAG with deterministic replay."""

from __future__ import annotations

import heapq
import json
from typing import Any


class EventGraph:
    """A directed acyclic graph of immutable events.

    Edges only point from a new event to events added earlier, so the
    structure can never contain a cycle. Inputs to :meth:`add` are copied,
    so later mutation of caller objects cannot pollute recorded history.
    """

    def __init__(self) -> None:
        self._at: dict[str, int] = {}
        self._parents: dict[str, tuple[str, ...]] = {}
        self._changes: dict[str, dict[str, int]] = {}

    @staticmethod
    def _require_nonempty_str(value: Any, name: str) -> None:
        if not isinstance(value, str):
            raise TypeError(f"{name} must be a str, got {type(value).__name__}")
        if not value:
            raise ValueError(f"{name} must be a non-empty str")

    @staticmethod
    def _require_int(value: Any, name: str) -> int:
        # bool is a subclass of int, but must not be accepted as one.
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{name} must be an int, got {type(value).__name__}")
        return value

    def add(
        self,
        id: str,
        at: int,
        parents: tuple[str, ...],
        changes: dict[str, int],
    ) -> None:
        """Add an event.

        Re-adding an existing ``id`` with identical ``at``, ``parents`` and
        ``changes`` is a no-op; any difference is a conflict.
        """
        # --- Full validation happens before any mutation. ---
        self._require_nonempty_str(id, "id")
        at_value = self._require_int(at, "at")
        if at_value < 0:
            raise ValueError("at must be a non-negative int")

        if not isinstance(parents, tuple):
            raise TypeError(f"parents must be a tuple, got {type(parents).__name__}")
        seen: set[str] = set()
        for parent in parents:
            self._require_nonempty_str(parent, "parent")
            if parent in seen:
                raise ValueError(f"duplicate parent {parent!r}")
            seen.add(parent)

        if not isinstance(changes, dict):
            raise TypeError(f"changes must be a dict, got {type(changes).__name__}")
        for key, value in changes.items():
            self._require_nonempty_str(key, "change key")
            self._require_int(value, f"change value for {key!r}")

        for parent in parents:
            if parent not in self._at:
                raise KeyError(parent)

        if id in self._at:
            if (
                self._at[id] != at_value
                or self._parents[id] != parents
                or self._changes[id] != changes
            ):
                raise ValueError(f"event {id!r} already exists with different inputs")
            return

        # --- Commit: store copies of caller-owned inputs. ---
        self._at[id] = at_value
        self._parents[id] = tuple(parents)
        self._changes[id] = dict(changes)

    def to_json(self) -> str:
        """Serialize the graph to a compact, deterministic JSON string.

        The top-level object contains only the ``events`` key. Events are
        ordered by the Unicode code point of their id; each event's keys
        are ordered ``id, at, parents, changes``, parent ids keep their
        recorded order, and change keys are sorted by Unicode code point.
        The output uses ``separators=(',', ':')``, ``ensure_ascii=False``
        and no trailing newline.
        """
        events: list[dict[str, object]] = []
        for event_id in sorted(self._at):
            events.append(
                {
                    "id": event_id,
                    "at": self._at[event_id],
                    "parents": list(self._parents[event_id]),
                    "changes": {
                        key: self._changes[event_id][key]
                        for key in sorted(self._changes[event_id])
                    },
                }
            )
        return json.dumps(
            {"events": events},
            separators=(",", ":"),
            ensure_ascii=False,
        )

    @classmethod
    def from_json(cls, payload: Any) -> "EventGraph":
        """Deserialize a string produced by :meth:`to_json`.

        Validation is strict and layered: a non-``str`` payload raises
        :class:`TypeError`; unparseable JSON, a wrong top-level shape,
        missing or extra fields, type errors, empty strings, negative
        timestamps, booleans posing as integers, duplicate event or
        parent ids, unknown parents, cycles and invalid change entries
        raise :class:`ValueError`. All validation finishes before the
        new graph is built, so a failure never leaves a partially
        populated object, and the result shares no mutable state with
        either the input string or the parsed JSON values.
        """
        if not isinstance(payload, str):
            raise TypeError(
                f"payload must be a str, got {type(payload).__name__}"
            )
        try:
            data = json.loads(payload)
        except json.JSONDecodeError as exc:
            raise ValueError(f"payload is not valid JSON: {exc}") from exc

        if not isinstance(data, dict):
            raise ValueError("top-level JSON value must be an object")
        if set(data.keys()) != {"events"}:
            raise ValueError(
                "top-level object must contain exactly the 'events' key"
            )
        raw_events = data["events"]
        if not isinstance(raw_events, list):
            raise ValueError("'events' must be an array")

        # Parse into fully local structures first; the EventGraph is only
        # constructed below, after every check has passed.
        at_values: dict[str, int] = {}
        parent_map: dict[str, tuple[str, ...]] = {}
        change_map: dict[str, dict[str, int]] = {}

        for index, event in enumerate(raw_events):
            if not isinstance(event, dict):
                raise ValueError(f"event at index {index} must be an object")
            if set(event.keys()) != {"id", "at", "parents", "changes"}:
                raise ValueError(
                    f"event at index {index} must contain exactly the keys "
                    "'id', 'at', 'parents' and 'changes'"
                )

            event_id = event["id"]
            if not isinstance(event_id, str) or not event_id:
                raise ValueError(
                    f"event at index {index}: id must be a non-empty str"
                )
            if event_id in at_values:
                raise ValueError(f"duplicate event id {event_id!r}")

            at_value = event["at"]
            # bool is a subclass of int, but must not be accepted as one.
            if isinstance(at_value, bool) or not isinstance(at_value, int):
                raise ValueError(f"event {event_id!r}: at must be an int")
            if at_value < 0:
                raise ValueError(f"event {event_id!r}: at must be non-negative")

            raw_parents = event["parents"]
            if not isinstance(raw_parents, list):
                raise ValueError(
                    f"event {event_id!r}: parents must be an array"
                )
            event_parents: list[str] = []
            seen_parents: set[str] = set()
            for parent in raw_parents:
                if not isinstance(parent, str) or not parent:
                    raise ValueError(
                        f"event {event_id!r}: every parent must be a "
                        "non-empty str"
                    )
                if parent in seen_parents:
                    raise ValueError(
                        f"event {event_id!r}: duplicate parent {parent!r}"
                    )
                seen_parents.add(parent)
                event_parents.append(parent)

            raw_changes = event["changes"]
            if not isinstance(raw_changes, dict):
                raise ValueError(
                    f"event {event_id!r}: changes must be an object"
                )
            event_changes: dict[str, int] = {}
            for key, value in raw_changes.items():
                if not isinstance(key, str) or not key:
                    raise ValueError(
                        f"event {event_id!r}: every change key must be a "
                        "non-empty str"
                    )
                if isinstance(value, bool) or not isinstance(value, int):
                    raise ValueError(
                        f"event {event_id!r}: change value for {key!r} "
                        "must be an int"
                    )
                event_changes[key] = value

            at_values[event_id] = at_value
            parent_map[event_id] = tuple(event_parents)
            change_map[event_id] = event_changes

        for event_id, event_parents in parent_map.items():
            for parent in event_parents:
                if parent not in at_values:
                    raise ValueError(
                        f"event {event_id!r}: unknown parent {parent!r}"
                    )

        # Cycle detection: iterative DFS following child -> parent edges.
        white, gray, black = 0, 1, 2
        color = {event_id: white for event_id in at_values}
        for start in at_values:
            if color[start] != white:
                continue
            color[start] = gray
            stack: list[tuple[str, int]] = [(start, 0)]
            while stack:
                node, cursor = stack[-1]
                node_parents = parent_map[node]
                if cursor < len(node_parents):
                    nxt = node_parents[cursor]
                    stack[-1] = (node, cursor + 1)
                    if color[nxt] == gray:
                        raise ValueError(
                            f"cycle detected involving event {nxt!r}"
                        )
                    if color[nxt] == white:
                        color[nxt] = gray
                        stack.append((nxt, 0))
                else:
                    color[node] = black
                    stack.pop()

        graph = cls()
        for event_id in at_values:
            graph._at[event_id] = at_values[event_id]
            graph._parents[event_id] = parent_map[event_id]
            graph._changes[event_id] = dict(sorted(change_map[event_id].items()))
        return graph

    def _ordered_ancestors(self, head: str) -> list[str]:
        """Validate ``head`` and return its ancestor closure in the unique
        parents-before-children order, ties among ready events broken by
        ``(at, id)`` ascending."""
        self._require_nonempty_str(head, "head")
        if head not in self._at:
            raise KeyError(head)

        closure: set[str] = {head}
        stack = [head]
        while stack:
            current = stack.pop()
            for parent in self._parents[current]:
                if parent not in closure:
                    closure.add(parent)
                    stack.append(parent)

        indegree = {event_id: 0 for event_id in closure}
        children: dict[str, list[str]] = {event_id: [] for event_id in closure}
        for event_id in closure:
            for parent in self._parents[event_id]:
                indegree[event_id] += 1
                children[parent].append(event_id)

        ready = [
            (self._at[event_id], event_id)
            for event_id, degree in indegree.items()
            if degree == 0
        ]
        heapq.heapify(ready)

        order: list[str] = []
        while ready:
            _, event_id = heapq.heappop(ready)
            order.append(event_id)
            for child in children[event_id]:
                indegree[child] -= 1
                if indegree[child] == 0:
                    heapq.heappush(ready, (self._at[child], child))
        return order

    def replay(self, head: str) -> dict[str, int]:
        """Accumulate changes over the ancestor closure of ``head``.

        Keys are kept (even at a zero value) once introduced, and the
        returned dict is ordered by Unicode code point of its keys.
        """
        order = self._ordered_ancestors(head)
        state: dict[str, int] = {}
        for event_id in order:
            for key, delta in self._changes[event_id].items():
                state[key] = state.get(key, 0) + delta
        return {key: state[key] for key in sorted(state)}

    def replay_at(self, head: str, at: int) -> dict[str, int]:
        """Replay ``head``'s ancestor closure as of timestamp ``at``.

        Only events whose own ``at`` is at most the given ``at`` are
        accumulated, in the same parents-before-children, ``(at, id)``
        order as :meth:`replay`. Keys are kept (even at a zero value)
        once introduced, and the returned dict is ordered by Unicode
        code point of its keys. The query is read-only: the graph and
        its events are never modified.
        """
        self._require_nonempty_str(head, "head")
        at_value = self._require_int(at, "at")
        if at_value < 0:
            raise ValueError("at must be a non-negative int")

        order = self._ordered_ancestors(head)
        state: dict[str, int] = {}
        for event_id in order:
            if self._at[event_id] > at_value:
                continue
            for key, delta in self._changes[event_id].items():
                state[key] = state.get(key, 0) + delta
        return {key: state[key] for key in sorted(state)}

    def diff_at(self, head_a: str, head_b: str, at: int) -> dict[str, tuple[int, int]]:
        """Compare two heads' ancestor closures as of timestamp ``at``.

        Each head is replayed with :meth:`replay_at`'s rules (only events
        whose own ``at`` is at most the given ``at``, parents-before-
        children in ``(at, id)`` order, zero-valued keys kept). The result
        is a fresh dict over the union of both states' keys, ordered by
        Unicode code point, mapping each key to a ``(left, right)`` tuple
        where a side missing the key contributes ``0``. All parameters
        are validated (in signature order) before either head is looked
        up; the query is read-only and its result is detached from the
        graph's internal state.
        """
        self._require_nonempty_str(head_a, "head_a")
        self._require_nonempty_str(head_b, "head_b")
        at_value = self._require_int(at, "at")
        if at_value < 0:
            raise ValueError("at must be a non-negative int")

        left = self.replay_at(head_a, at_value)
        right = self.replay_at(head_b, at_value)
        return {
            key: (left.get(key, 0), right.get(key, 0))
            for key in sorted(left.keys() | right.keys())
        }

    def explain(self, head: str, key: str) -> tuple[str, ...]:
        """Return ids of events touching ``key``, in replay order.

        Events carrying a zero delta for the key are included.
        """
        self._require_nonempty_str(key, "key")
        order = self._ordered_ancestors(head)
        return tuple(
            event_id for event_id in order if key in self._changes[event_id]
        )

def _evaluate_subset_view(
    self,
    member_views: list[list[tuple[list[str], list[str], str, str]]],
    ordered_keys: tuple[str, ...],
    weights: dict[str, int | float],
    key_budgets: dict[str, int | float],
    total_budget: int | float,
) -> tuple[object, ...]:
    """Apply the combination-budget accounting to one enumerated subset.

    Returns a reject tuple ``("reject", checkpoint, reason, key,
    overrun)`` at the earliest breaching checkpoint -- the total budget
    before the first per-key breach in Unicode key order -- or a
    feasible tuple carrying the final checkpoint's risk, per-key
    aggregate, per-member signed differences and captured positions.
    An empty subset (or a pool without checkpoints) is feasible with
    zero risk. All inputs come from the caller's captured read-only
    view.
    """
    point_count = len(member_views[0]) if member_views else 0
    final_risk: int | float = 0
    final_aggregate: dict[str, int] = {}
    final_member_diffs: list[dict[str, int]] = []
    final_position: list[
        tuple[list[str], list[str], str, str]
    ] | None = None

    for index in range(point_count):
        position = [views[index] for views in member_views]
        # Pool alignment guarantees every member shares this checkpoint's
        # reference node, so its values are replayed once per point.
        reference_order = position[0][0]
        reference_values = {
            key: self._replayed_value(reference_order, key)
            for key in ordered_keys
        }
        aggregate: dict[str, int] = {key: 0 for key in ordered_keys}
        member_diffs: list[dict[str, int]] = []
        for _, right_order, _, _ in position:
            diffs: dict[str, int] = {}
            for key in ordered_keys:
                diff = (
                    self._replayed_value(right_order, key)
                    - reference_values[key]
                )
                diffs[key] = diff
                aggregate[key] += diff
            member_diffs.append(diffs)

        risk: int | float = 0
        for key in ordered_keys:
            risk += abs(aggregate[key]) * weights[key]
        if risk == 0:
            risk = 0 if isinstance(risk, int) else 0.0

        # At one checkpoint the total breach outranks every per-key
        # breach; the first breaching key by Unicode order is reported.
        if risk > total_budget:
            return (
                "reject",
                index,
                "total_budget",
                None,
                risk - total_budget,
            )
        for key in ordered_keys:
            if (
                key in key_budgets
                and abs(aggregate[key]) > key_budgets[key]
            ):
                return (
                    "reject",
                    index,
                    "key_budget",
                    key,
                    (abs(aggregate[key]) - key_budgets[key])
                    * weights[key],
                )

        final_risk = risk
        final_aggregate = aggregate
        final_member_diffs = member_diffs
        final_position = position

    return (
        "feasible",
        final_risk,
        final_aggregate,
        final_member_diffs,
        final_position,
    )

@staticmethod
def _require_size_bound(value: Any, name: str) -> int:
    """Validate one non-``bool`` integer size/search parameter.

    ``min_size``, ``max_size`` and ``limit`` share the contract: a
    :class:`bool` or any non-:class:`int` value raises
    :class:`TypeError`; the value's range is the caller's concern.
    """
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(
            f"{name} must be an int, got {type(value).__name__}"
        )
    return value

@staticmethod
def _require_finite_budget(value: Any, name: str) -> None:
    """Validate one budget number, shared by the total and per-key maps.

    A :class:`bool` or any non-:class:`int`/:class:`float` value raises
    :class:`TypeError`; a NaN or infinite value raises
    :class:`ValueError` before the sign is checked, and a negative
    number raises :class:`ValueError`. Zero (int or float) is accepted.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(
            f"{name} must be an int or float, got {type(value).__name__}"
        )
    if isinstance(value, float) and (
        math.isnan(value) or math.isinf(value)
    ):
        raise ValueError(f"{name} must be finite")
    if value < 0:
        raise ValueError(f"{name} must be non-negative")

@staticmethod
def _validate_weights(weights: Any) -> tuple[str, ...]:
    """Validate ``weights`` and return its keys in Unicode order.

    The weight-map counterpart of :meth:`_validate_keys`: a non-dict
    raises :class:`TypeError`; entries are walked in insertion order,
    a non-``str`` key raising :class:`TypeError` and an empty key
    raising :class:`ValueError`; each weight must be a non-``bool``
    :class:`int` or :class:`float` (else :class:`TypeError`) and must
    not be negative, NaN or infinite (else :class:`ValueError`).
    """
    if not isinstance(weights, dict):
        raise TypeError(
            f"weights must be a dict, got {type(weights).__name__}"
        )
    for key, value in weights.items():
        EventGraph._require_nonempty_str(key, "weight key")
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(
                f"weight for {key!r} must be an int or float, got "
                f"{type(value).__name__}"
            )
        if isinstance(value, float) and (
            math.isnan(value) or math.isinf(value)
        ):
            raise ValueError(f"weight for {key!r} must be finite")
        if value < 0:
            raise ValueError(f"weight for {key!r} must be non-negative")
    return tuple(sorted(weights))

@staticmethod
def _copy_attribution(
    record: dict[str, Any],
) -> dict[str, object]:
    """Deep-copy a ``key, fork, left, right`` attribution dict.

    The copied result shares no tuples or dicts with the source, so it
    stays detached from the per-call attributions and internal state.
    """
    def copy_side(side: dict[str, Any]) -> dict[str, object]:
        return {
            "value": side["value"],
            "cause": side["cause"],
            "path": tuple(side["path"]),
            "affected": tuple(side["affected"]),
        }

    return {
        "key": record["key"],
        "fork": record["fork"],
        "left": copy_side(record["left"]),
        "right": copy_side(record["right"]),
    }

@staticmethod
def _validate_points(points: Any) -> None:
    """Validate a tuple of length-2, unique node-id pairs.

    Shared by :meth:`divergence_timeline`, :meth:`divergence_summary`
    and :meth:`divergence_matrix` so points raise identical errors: a
    non-tuple container or non-length-2-tuple point raises
    :class:`TypeError`, non-``str`` or empty node ids raise
    :class:`TypeError`/:class:`ValueError` (left node before right),
    and a repeated node pair raises :class:`ValueError`.
    """
    if not isinstance(points, tuple):
        raise TypeError(
            f"points must be a tuple, got {type(points).__name__}"
        )
    seen_points: set[tuple[str, str]] = set()
    for point in points:
        if not isinstance(point, tuple) or len(point) != 2:
            raise TypeError(
                "each point must be a length-2 tuple of node ids, "
                f"got {point!r} ({type(point).__name__})"
            )
        node_a, node_b = point
